export type LvrtEnginePluginPdas = {
  config: typeof findConfigPda;
  engineSigner: typeof findEngineSignerPda;
  trigger: typeof findTriggerPda;
};

export type LvrtEnginePluginRequirements = ClientWithRpc<
  GetAccountInfoApi & GetMultipleAccountsApi
> &
  ClientWithPayer &
  ClientWithTransactionPlanning &
  ClientWithTransactionSending;

export function lvrtEngineProgram() {
  return <T extends LvrtEnginePluginRequirements>(
    client: T,
  ): ExtendedClient<T, { lvrtEngine: LvrtEnginePlugin }> => {
    return extendClient(client, {
      lvrtEngine: {
        accounts: {
          bucketRisk: addSelfFetchFunctions(client, getBucketRiskCodec()),
          engineConfig: addSelfFetchFunctions(client, getEngineConfigCodec()),
          fundingState: addSelfFetchFunctions(client, getFundingStateCodec()),
          marginAccount: addSelfFetchFunctions(client, getMarginAccountCodec()),
          market: addSelfFetchFunctions(client, getMarketCodec()),
          marketShard: addSelfFetchFunctions(client, getMarketShardCodec()),
          position: addSelfFetchFunctions(client, getPositionCodec()),
          trigger: addSelfFetchFunctions(client, getTriggerCodec()),
        },
        instructions: {
          applyCorporateAction: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getApplyCorporateActionInstruction(input),
            ),
          autoDeleverage: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getAutoDeleverageInstructionAsync(input),
            ),
          cancelTrigger: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCancelTriggerInstruction(input),
            ),
          claimQueuedProfit: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getClaimQueuedProfitInstruction(input),
            ),
          closePosition: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getClosePositionInstruction(input),
            ),
          createMarginAccount: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateMarginAccountInstruction(input),
            ),
          createMarket: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateMarketInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          declareCorporateAction: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getDeclareCorporateActionInstructionAsync(input),
            ),
          deposit: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getDepositInstructionAsync(input),
            ),
          depositUsdt: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getDepositUsdtInstruction(input),
            ),
          executeTrigger: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getExecuteTriggerInstruction(input),
            ),
          initCustody: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitCustodyInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          initShard: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitShardInstruction({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          initialize: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitializeInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          liquidate: (input) =>
            addSelfPlanAndSendFunctions(client, getLiquidateInstruction(input)),
          mergeShards: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getMergeShardsInstruction(input),
            ),
          openPosition: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getOpenPositionInstructionAsync(input),
            ),
          placeTrigger: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getPlaceTriggerInstructionAsync(input),
            ),
          setAdlParams: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetAdlParamsInstructionAsync(input),
            ),
          setDelegate: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetDelegateInstruction(input),
            ),
          setMarketFlags: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetMarketFlagsInstructionAsync(input),
            ),
          setMarketRisk: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetMarketRiskInstructionAsync(input),
            ),
          setOpensPaused: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetOpensPausedInstructionAsync(input),
            ),
          setRoles: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetRolesInstructionAsync(input),
            ),
          settleShard: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSettleShardInstructionAsync(input),
            ),
          withdraw: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getWithdrawInstructionAsync(input),
            ),
        },
        pdas: {
          config: findConfigPda,
          engineSigner: findEngineSignerPda,
          trigger: findTriggerPda,
        },
        identifyAccount: identifyLvrtEngineAccount,
        identifyInstruction: identifyLvrtEngineInstruction,
        parseInstruction: parseLvrtEngineInstruction,
      } as LvrtEnginePlugin,
    });
  };
}

type MakeOptional<T, K extends keyof T> = Omit<T, K> & Partial<Pick<T, K>>;
